<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CareRoute · Role Login</title><link rel="icon" href="{{ asset(config('branding.logo')) }}" type="image/svg+xml"><style>*{box-sizing:border-box}body{margin:0;background:#f3f6f9;color:#102e49;font:14px/1.6 system-ui}main{max-width:980px;margin:8vh auto;padding:24px;display:grid;grid-template-columns:1fr 1fr;gap:30px}section{background:white;padding:30px;border:1px solid #dce5eb;border-radius:16px}img{width:60px}h1{font-size:28px;margin:10px 0}label{display:block;margin:15px 0 5px}input{width:100%;padding:12px;border:1px solid #ccd8e1;border-radius:8px;font:inherit}button{width:100%;margin-top:20px;background:#087f78;color:white;border:0;border-radius:8px;padding:13px;font:inherit;font-weight:700;cursor:pointer}p,small{color:#63758a}.account{padding:12px 0;border-bottom:1px solid #dce5eb}.account strong{display:block}.error{background:#fff0ee;color:#b3312c;padding:10px;border-radius:8px}code{background:#edf7f6;padding:3px 6px}.badge{font-size:11px;color:#836016;background:#fff5d9;padding:5px 9px;border-radius:12px}@media(max-width:700px){main{grid-template-columns:1fr;margin:20px auto}}</style></head><body><main><section><img src="{{ asset(config('branding.logo')) }}" alt="Hospital logo"><h1>Welcome to CareRoute</h1><p>Sign in to your assigned workspace.</p>@if($errors->any())<div class="error">{{ $errors->first() }}</div>@endif<form method="POST" action="{{ route('login') }}">@csrf<input type="hidden" name="college_id" value="1"><label for="email">Email / User ID</label><input id="email" name="email" value="{{ old('email') }}" required autocomplete="username"><label for="password">Password</label><input id="password" type="password" name="password" required autocomplete="current-password"><button>Sign in</button></form><p><small>Use separate browser profiles or sign out to switch roles.</small></p></section><section><span class="badge">M